void AnimarGemasCaen(List<(int, int)> listaGemas, List<(int, int)> listaPrimerBlanco)
{
    foreach (var col in listaPrimerBlanco)
    {
        var gemas = listaGemas.Where(x => x.Item2 == col.Item2).ToList();
        var target = positions.FirstOrDefault(p => p.row == col.Item1 && p.col == col.Item2);
        int i = 0;
        foreach (var gema in gemas)
        {
            GameObject gem = GameObject.Find($"Piece_{gema.Item1}_{gema.Item2}");
            gem.transform.DOMoveY(target.y, 1f).SetEase(Ease.InFlash).SetDelay(2f + i / 2f);
            gem.name = $"Piece_{col.Item1 - i}_{col.Item2}";
            if (col.Item1 - i >= 0) target = positions.FirstOrDefault(p => p.row == col.Item1 - i && p.col == col.Item2);
            i++;
        }
    }
}
